export const courseNotes: Record<TrackId,{key:string; question:string; answer:string}> = {
  ocean:{key:"Depth provides a coordinate. Pressure, visibility, temperature, and life are separate variables with different causes.",
    question:"Where do ocean depth-zone names come from?",answer:"They divide the water column into useful ranges. Terminology and depths vary somewhat by classification, and local conditions can differ within a range. Use the ranges stated by the particular chart."},
  earth:{key:"Relative ages order events. Numerical dates tie a suitable material and event to a clock.",
    question:"Why are plate borders drawn as lines while mountains occupy broad areas?",answer:"A line generalizes a boundary from available data. Deformation may spread across multiple faults and structures over a much wider area."},
  climate:{key:"Read each climate record against its reference period, measurement method, and geographic scale.",
    question:"Can I compare two graphs with different reference periods?",answer:"You can often compare trends over the same interval. Comparing plotted levels requires checking or adjusting their reference periods and confirming that the graphs represent the same quantity."},
  life:{key:"A record of presence is evidence from a specific search. A study of abundance needs information about sampling effort and detection.",
    question:"Why compare reference sites alongside a conservation intervention?",answer:"Changes such as a hot season, heavy rain, or a survey method change can affect multiple sites. A reference helps estimate what might have happened without the intervention."},
  space:{key:"A telescope measures light in wavelength bands. Distances, masses, and histories are derived with models and supporting observations.",
    question:"Why do astronomers use several filters for one field?",answer:"Different wavelength bands can distinguish features that are mixed in a single band. For example, dust may obscure visible light while allowing some longer wavelengths to pass."},
  population:{key:"A useful demographic comparison states the year, denominator, definitions, and whether results are estimates or projections.",
    question:"Why is a population pyramid for one country sometimes less reliable than another?",answer:"Census frequency, completeness of vital registration, coverage, and methods differ. Estimates may draw on several sources and use models where observations are sparse."},
  systems:{key:"A strong interdisciplinary argument connects a proposed mechanism to independent evidence at compatible scales.",
    question:"What should I do if two sources seem to disagree?",answer:"Compare what and where they measured, their methods and reference periods, and the uncertainty in each. A disagreement may identify a useful new question rather than a faulty source."},
};
